import java.io.*;import java.util.*;import com.jpexs.decompiler.flash.*;
public class ComparePhysics{public static void main(String[] v)throws Exception{SWF x=new SWF(new FileInputStream(v[0]),false),y=new SWF(new FileInputStream(v[1]),false);int same=0,diff=0;for(int z=0;z<x.getAbcList().size();z++){var a=x.getAbcList().get(z).getABC();var b=y.getAbcList().get(z).getABC();for(int i=0;i<a.bodies.size();i++){if(Arrays.equals(a.bodies.get(i).getCodeBytes(),b.bodies.get(i).getCodeBytes()))same++;else {diff++;System.out.println("Changed method index "+i);}}}System.out.println("Same="+same+" Changed="+diff);}}
